def compress(ids):
    ids = [i for i in ids if i]
    by = collections.OrderedDict()
    for i in ids:
        p, n = i.rsplit("-", 1); by.setdefault(p, []).append(int(n))
    out = []
    for p, ns in by.items():
        ns = sorted(set(ns)); a = b = ns[0]; segs = []
        for n in ns[1:]:
            if n == b + 1: b = n
            else: segs.append((a, b)); a = b = n
        segs.append((a, b))
        out.append(", ".join(f"{p}-{x:02d}" if x == y else f"{p}-{x:02d}…{y:02d}" for x, y in segs))
    return "; ".join(out)

